from types import SimpleNamespace
from glob import glob

def readobs(path):
 return SimpleNamespace(meta=json.load(open(path+'/meta.json')),last={c:np.array(Image.open(path+'/last/'+c+'.jpg')) for c in cams},depth={c:np.load(path+'/depth_'+c+'.npy') for c in cams})
