def icp_fixed(P,Q,R):
 tree=cKDTree(Q);p=P@R.T;t=np.median(Q,0)-np.median(p,0)
 for _ in range(80):
  d,idx=tree.query(p+t);m=d<np.quantile(d,.8);tt=np.mean(Q[idx[m]]-p[m],0)
  if np.linalg.norm(t-tt)<1e-7:break
  t=tt
 return t,np.sqrt(np.mean(d[m]**2))

P0=hcloud(readobs('/app/runs/initial'));tw=[]
for j in range(7):
 oo=readobs(glob('/app/runs/*_probe'+str(j))[0]);Q=hcloud(oo)
 delta=np.array(oo.meta['proprio']['now'][:7])[j]-q0[j];R=Rot.from_rotvec(axes[j]*delta).as_matrix();t,e=icp_fixed(P0,Q,R)
 # revolute axis with t=(I-R)c; infer c perpendicular axis
 cc=np.linalg.lstsq(np.eye(3)-R,t,rcond=1e-5)[0]
 v=-np.cross(axes[j],cc);tw.append([axes[j],v]);print(j,'axis_point',cc,'error',e)
twists=np.array(tw)

def skew(w):return np.array([[0,-w[2],w[1]],[w[2],0,-w[0]],[-w[1],w[0],0]])

def fk(a):
 T=np.eye(4)
 for j in range(7):
  w,v=twists[j];th=a[j]-q0[j];W=skew(w);R=Rot.from_rotvec(w*th).as_matrix();V=np.eye(3)*th+(1-np.cos(th))*W+(th-np.sin(th))*W@W
  E=np.eye(4);E[:3,:3]=R;E[:3,3]=V@v;T=T@E
 return T

def ik(T,seed=None):
 if seed is None:seed=q[:7]
 def res(a):
  F=fk(a);return np.r_[ (F[:3,3]-T[:3,3])*4,Rot.from_matrix(F[:3,:3]@T[:3,:3].T).as_rotvec(),(a-seed)*.001]
 sol=least_squares(res,seed,bounds=(np.array(spec['action_types']['joint_position']['lower'][:7]),np.array(spec['action_types']['joint_position']['upper'][:7])),xtol=1e-10,gtol=1e-10,ftol=1e-10)
 print('IK',np.linalg.norm(res(sol.x)[:6]));return np.r_[sol.x,q[7:]]

def shift(d,seconds=1.5):
