def posemat(g):
 T=np.eye(4);T[:3,:3]=Rot.from_quat(g[3:]).as_matrix();T[:3,3]=g[:3];return T

def apply(T,P):return P@T[:3,:3].T+T[:3,3]

def ghostmodel(o):
 G=gcloud(o);T=posemat(o.meta['task']['goal']);M=apply(np.linalg.inv(T),G)
 m=(abs(M[:,0])<.11)&(abs(M[:,1])<.03)&(M[:,2]>-.08)&(M[:,2]<.018)
