  p=cloud(o,c);im=o.last[c].astype(float);m=np.all((p>lo)&(p<hi),2)&~((im[:,:,1]>im[:,:,0]+25)&(im[:,:,1]>im[:,:,2]+25))
  ps.append(p[m]);cs.append(im[m])
